From 3cf4375a090473d240281a0d2b04a3a5aaeac34b Mon Sep 17 00:00:00 2001
From: Xin Long <lucien.xin@gmail.com>
Date: Fri, 23 Jul 2021 18:46:01 -0400
Subject: [PATCH] tipc: do not write skb_shinfo frags when doing decrytion

One skb's skb_shinfo frags are not writable, and they can be shared with
other skbs' like by pskb_copy(). To write the frags may cause other skb's
data crash.

So before doing en/decryption, skb_cow_data() should always be called for
a cloned or nonlinear skb if req dst is using the same sg as req src.
While at it, the likely branch can be removed, as it will be covered
by skb_cow_data().

Note that esp_input() has the same issue, and I will fix it in another
patch. tipc_aead_encrypt() doesn't have this issue, as it only processes
linear data in the unlikely branch.

Fixes: fc1b6d6de220 ("tipc: introduce TIPC encryption & authentication")
Reported-by: Shuang Li <shuali@redhat.com>
Signed-off-by: Xin Long <lucien.xin@gmail.com>
Acked-by: Jon Maloy <jmaloy@redhat.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

diff --git a/net/tipc/crypto.c b/net/tipc/crypto.c
index e5c43d4d5a75..c9391d38de85 100644
--- a/net/tipc/crypto.c
+++ b/net/tipc/crypto.c
@@ -898,16 +898,10 @@ static int tipc_aead_decrypt(struct net *net, struct tipc_aead *aead,
 	if (unlikely(!aead))
 		return -ENOKEY;

-	/* Cow skb data if needed */
-	if (likely(!skb_cloned(skb) &&
-		   (!skb_is_nonlinear(skb) || !skb_has_frag_list(skb)))) {
-		nsg = 1 + skb_shinfo(skb)->nr_frags;
-	} else {
-		nsg = skb_cow_data(skb, 0, &unused);
-		if (unlikely(nsg < 0)) {
-			pr_err("RX: skb_cow_data() returned %d\n", nsg);
-			return nsg;
-		}
+	nsg = skb_cow_data(skb, 0, &unused);
+	if (unlikely(nsg < 0)) {
+		pr_err("RX: skb_cow_data() returned %d\n", nsg);
+		return nsg;
 	}

 	/* Allocate memory for the AEAD operation */
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the fact that the `skb_shinfo frags` of a socket buffer (skb) are not writable and can be shared among different skbs. Writing to these frags without ensuring they are safely copied can lead to data corruption and crashes, especially when the same scatter-gather (sg) list is used for both the request source and destination. The previous logic did not adequately handle the case for cloned or nonlinear skbs, which could result in unsafe modifications to shared data during encryption and decryption processes.

        Commit message:
        tipc: do not write skb_shinfo frags when doing decrytion

One skb's skb_shinfo frags are not writable, and they can be shared with
other skbs' like by pskb_copy(). To write the frags may cause other skb's
data crash.

So before doing en/decryption, skb_cow_data() should always be called for
a cloned or nonlinear skb if req dst is using the same sg as req src.
While at it, the likely branch can be removed, as it will be covered
by skb_cow_data().

Note that esp_input() has the same issue, and I will fix it in another
patch. tipc_aead_encrypt() doesn't have this issue, as it only processes
linear data in the unlikely branch.

Fixes: fc1b6d6de220 ("tipc: introduce TIPC encryption & authentication")
Reported-by: Shuang Li <shuali@redhat.com>
Signed-off-by: Xin Long <lucien.xin@gmail.com>
Acked-by: Jon Maloy <jmaloy@redhat.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:
          */
 static int tipc_aead_decrypt(struct net *net, struct tipc_aead *aead,
 			     struct sk_buff *skb, struct tipc_bearer *b)
 {
 	struct tipc_crypto_rx_ctx *rx_ctx;
 	struct aead_request *req;
 	struct crypto_aead *tfm;
 	struct sk_buff *unused;
 	struct scatterlist *sg;
 	struct tipc_ehdr *ehdr;
 	int ehsz, nsg, rc;
 	void *ctx;
 	u32 salt;
 	u8 *iv;

 	if (unlikely(!aead))
 		return -ENOKEY;

-	/* Cow skb data if needed */
-	if (likely(!skb_cloned(skb) &&
-		   (!skb_is_nonlinear(skb) || !skb_has_frag_list(skb)))) {
-		nsg = 1 + skb_shinfo(skb)->nr_frags;
-	} else {
-		nsg = skb_cow_data(skb, 0, &unused);
-		if (unlikely(nsg < 0)) {
-			pr_err("RX: skb_cow_data() returned %d\n", nsg);
-			return nsg;
-		}
+	nsg = skb_cow_data(skb, 0, &unused);
+	if (unlikely(nsg < 0)) {
+		pr_err("RX: skb_cow_data() returned %d\n", nsg);
+		return nsg;
 	}

 	/* Allocate memory for the AEAD operation */
 	tfm = tipc_aead_tfm_next(aead);
 	ctx = tipc_aead_mem_alloc(tfm, sizeof(*rx_ctx), &iv, &req, &sg, nsg);
 	if (unlikely(!ctx))
 		return -ENOMEM;
 	TIPC_SKB_CB(skb)->crypto_ctx = ctx;

 	/* Map skb to the sg lists */
 	sg_init_table(sg, nsg);
 	rc = skb_to_sgvec(skb, sg, 0, skb->len);
 	if (unlikely(rc < 0)) {
 		pr_err("RX: skb_to_sgvec() returned %d, nsg %d\n", rc, nsg);
 		goto exit;
 	}

 	/* Reconstruct IV: */
 	ehdr = (struct tipc_ehdr *)skb->data;
 	salt = aead->salt;
 	if (aead->mode == CLUSTER_KEY)
 		salt ^= __be32_to_cpu(ehdr->addr);
 	else if (ehdr->destined)
 		salt ^= tipc_own_addr(net);
 	memcpy(iv, &salt, 4);
 	memcpy(iv + 4, (u8 *)&ehdr->seqno, 8);

 	/* Prepare request */
 	ehsz = tipc_ehdr_size(ehdr);
 	aead_request_set_tfm(req, tfm);
 	aead_request_set_ad(req, ehsz);
 	aead_request_set_crypt(req, sg, sg, skb->len - ehsz, iv);

 	/* Set callback function & data */
 	aead_request_set_callback(req, CRYPTO_TFM_REQ_MAY_BACKLOG,
 				  tipc_aead_decrypt_done, skb);
 	rx_ctx = (struct tipc_crypto_rx_ctx *)ctx;
 	rx_ctx->aead = aead;
 	rx_ctx->bearer = b;

 	/* Hold bearer */
 	if (unlikely(!tipc_bearer_hold(b))) {
 		rc = -ENODEV;
 		goto exit;
 	}

 	/* Now, do decrypt */
 	rc = crypto_aead_decrypt(req);
 	if (rc == -EINPROGRESS || rc == -EBUSY)
 		return rc;

 	tipc_bearer_put(b);

 exit:
 	kfree(ctx);
 	TIPC_SKB_CB(skb)->crypto_ctx = NULL;
 	return rc;
 }



